--
-- Table structure for table `sections`
--

DROP TABLE IF EXISTS `sections`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sections` (
  `section_id` int NOT NULL AUTO_INCREMENT,
  `term_id` int NOT NULL,
  `course_id` int NOT NULL,
  `primary_instructor_id` int DEFAULT NULL,
  `secondary_instructor_id` int DEFAULT NULL,
  `section_code` varchar(50) NOT NULL,
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `delivery_method` varchar(100) DEFAULT NULL,
  `course_attribute` text,
  `class_comments` longtext,
  `avail_seats` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`section_id`),
  UNIQUE KEY `uniq_section` (`term_id`,`course_id`,`section_code`),
  KEY `fk_sections_course` (`course_id`),
  KEY `fk_sections_primary_instructor` (`primary_instructor_id`),
  KEY `fk_sections_secondary_instructor` (`secondary_instructor_id`),
  CONSTRAINT `fk_sections_course` FOREIGN KEY (`course_id`) REFERENCES `courses` (`course_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_sections_primary_instructor` FOREIGN KEY (`primary_instructor_id`) REFERENCES `instructors` (`instructor_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_sections_secondary_instructor` FOREIGN KEY (`secondary_instructor_id`) REFERENCES `instructors` (`instructor_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_sections_term` FOREIGN KEY (`term_id`) REFERENCES `terms` (`term_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6190 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

